class Solution:
    def replaceElements(self, arr: list[int]) -> list[int]:
        best = -1                              # max of the elements to the right; -1 for the last slot
        for i in range(len(arr) - 1, -1, -1):  # one pass from the right: O(n)
            arr[i], best = best, max(best, arr[i])   # write first, then fold the old value in
        return arr
